Also, the last sections in transform.hpp have a lot of non-idiomatic Eigen. I think we can do something like

    template <typename T>
    Matrix<T,Dynamic,Dynamic> cov_matrix_constrain(const Matrix<T,Dynamic,1>& x,
                                                   size_t k,
                                                   T& lp) {
      size_t k_choose_2 = (k * (k - 1)) / 2;
      Array<T,Dynamic,1> cpcs = x.head(k_choose_2).array().tanh();
      Array<T,Dynamic,1> sds = x.tail(k).array().exp();
      return read_cov_matrix(cpcs, sds, lp);
    }

